const LOADERS = { mlb,nfl,nba,wnba,nhl,ufc,tennis,soccer,golf,f1 };

export { SPORTS, LOADERS };

// members-live/1 board for the requested sports (comma list; empty = all). Never throws: a failing source
// is reported as state "unavailable" with its error, exactly like the Members route.
export async function loadBoard(sports = '') {
  const wanted = String(sports || '').trim().toLowerCase();
  const keys = wanted ? wanted.split(',').filter((x) => SPORTS.includes(x)) : SPORTS;
  const started = Date.now();
  const settled = await Promise.all(keys.map(async (key) => {
    const at = Date.now();
    try {
      const result = await LOADERS[key]();
      return {key,state:'ok',ms:Date.now()-at,...result};
    } catch (error) {
      return {key,state:'unavailable',ms:Date.now()-at,fetched_at:null,items:[],error:error instanceof Error ? error.message : 'unavailable'};
    }
  }));

  const items = settled.flatMap((s) => s.items).sort((a,b) => {
    const rank = (x) => x.status === 'live' ? 0 : x.status === 'scheduled' ? 1 : x.status === 'final' ? 2 : 3;
    const r = rank(a)-rank(b);
    if (r) return r;
    return String(a.starts_at || '').localeCompare(String(b.starts_at || ''));
  });

  return {
    contract:'members-live/1',
    generated_at:NOW(),
    duration_ms:Date.now()-started,
    live_count:items.filter((x) => x.status === 'live').length,
    total:items.length,
    items,
    sources:settled.map(({key,state,ms,fetched_at,items,error}) => ({key,state,ms,fetched_at,count:items.length,...(error?{error}:{} )}))
  };
}
